def transform(grid):
    g = np.array(grid)
    bg = background(g)
    out = g.copy()
    ys, xs = np.nonzero(g != bg)
    if len(ys) == 0:
        emit(out, "No markers: nothing to frame.")
        return out
    y0, y1, x0, x1 = ys.min(), ys.max(), xs.min(), xs.max()
    # top and bottom edges
    for x in range(x0, x1 + 1):
        for y in (y0, y1):
            if out[y, x] == bg:
                out[y, x] = 1
    emit(out, f"Bounding box of the 8 markers is rows {y0}-{y1}, cols {x0}-{x1}; draw its top and bottom edges in colour 1, keeping the 8s.")
    # left and right edges
    for y in range(y0, y1 + 1):
        for x in (x0, x1):
            if out[y, x] == bg:
                out[y, x] = 1
    emit(out, "Draw the left and right edges, completing the rectangle that passes through all three 8s.")
    return out
